// prettier-ignore
const hours = [
  '12:00', '1:00', '2:00', '3:00', '4:00', '5:00', '6:00',
  '7:00', '8:00', '9:00', '10:00', '11:00',
  '12:00', '13:00', '14:00', '15:00', '16:00', '17:00',
  '18:00', '19:00', '20:00', '21:00', '22:00', '23:00'
];
// prettier-ignore
const days = [
  'Mon', 'Tue', 'Wed',
  'Thu', 'Fri', 'Sat', 'Sun',
].reverse();

const dayMap = {
  0: days.indexOf('Sun'),
  1: days.indexOf('Mon'),
  2: days.indexOf('Tue'),
  3: days.indexOf('Wed'),
  4: days.indexOf('Thu'),
  5: days.indexOf('Fri'),
  6: days.indexOf('Sat'),
};


const round = (val, decimal = 2) => Math.round(val * 10 ** decimal) / 10 ** decimal;

// prettier-ignore
const data = [];
// x = hour, y = dow, z = value
if (context.panel.data.series[0]) {
  for (let i = 0; i < context.panel.data.series[0].length ?? 0; i += 1) {
    let dow = context.panel.data.series[0].fields[0].values[i];
    const hour = context.panel.data.series[0].fields[1].values[i];
    const eff = context.panel.data.series[0].fields[2].values[i];
    data.push([hour, dayMap[dow], round(eff) || '-'])
  }
}

option = {
  tooltip: {
    position: 'top',
    formatter: (params) => {
      const [hourIndex, dayIndex, value] = params.value;

      return [
        `${days[dayIndex]}, ${hours[hourIndex]}`,
        `<strong>${Number(value).toFixed(2)} kW/RT</strong>`
      ].join('<br>');
    }
  },
  grid: {
    height: '80%',
    top: '20',
    left: '50',
    right: '80',
  },
  xAxis: {
    type: 'category',
    data: hours,
    splitArea: {
      show: true
    }
  },
  yAxis: {
    type: 'category',
    data: days,
    splitArea: {
      show: true
    }
  },
  visualMap: {
    min: 0,
    max: 2,
    color: [
      '#d44a3a',
      '#eb7b18',
      '#299c46',
    ],
    formatter: (value) => `${Number(value).toFixed(1)} kW/RT`,
    calculable: false,
    precision: 1,
    orient: 'vertical',
    top: 'center',
    right: 20,
  },
  series: [
    {
      name: 'Punch Card',
      type: 'heatmap',
      data: data,
      label: {
        show: false
      },
      emphasis: {
        itemStyle: {
          shadowBlur: 10,
          shadowColor: 'rgba(0, 0, 0, 0.5)'
        }
      }
    }
  ]
};

return option;

